const raw = $json.entry?.[0]?.changes?.[0]?.value ?? $json;
const message = raw.messages?.[0] ?? null;
const contact = raw.contacts?.[0] ?? null;
if (!message) return {json:{event_type:'IGNORE', reason:'NO_MESSAGE', raw}};
const type = String(message.type ?? 'unknown').toLowerCase();
let text = message.text?.body ?? null;
let interaction = null;
let media = null;

if (type === 'interactive') {
  const reply = message.interactive?.button_reply ?? message.interactive?.list_reply ?? null;
  if (reply) {
    const id = String(reply.id ?? '');
    const slot = id.match(/^slot\|([0-9a-f-]{36})\|(\d+)$/i);
    const rebook = id.match(/^rebook\|([0-9a-f-]{36})$/i);
    interaction = {
      kind: message.interactive?.button_reply ? 'BUTTON_REPLY' : 'LIST_REPLY',
      reply_id: id,
      title: reply.title ?? null,
      action: slot ? 'SELECT_SLOT' : rebook ? 'REBOOK_APPOINTMENT' : null,
      slot_offer_id: slot ? slot[1] : null,
      option_number: slot ? Number(slot[2]) : null,
      appointment_id: rebook ? rebook[1] : null
    };
    text = reply.title ?? text;
  }
}
if (['audio','image','document','video','sticker'].includes(type)) {
  const m = message[type] ?? {};
  media = {id:m.id ?? null, mime_type:m.mime_type ?? null, sha256:m.sha256 ?? null,
           caption:m.caption ?? null, filename:m.filename ?? null};
  text = m.caption ?? text;
}
const ts = message.timestamp ? new Date(Number(message.timestamp)*1000).toISOString() : new Date().toISOString();
return {json:{
  event_type:'INBOUND_MESSAGE',
  channel:{type:'WHATSAPP',provider:'META',external_channel_id:raw.metadata?.phone_number_id ?? null},
  customer:{external_user_id:message.from ?? null,profile_name:contact?.profile?.name ?? null},
  message:{external_message_id:message.id ?? null,idempotency_key:message.id ? `IN:META:${message.id}` : null,
           type,text,interaction,media,reply_to_external_message_id:message.context?.id ?? null,
           provider_timestamp:ts,raw_payload:raw},
  received_at:new Date().toISOString()
}};
